// Benchmark results, generated by `pnpm bench` in the repository root (benchmark/results.json).
// The JSON is bundled at build time, so the page always shows the numbers of this exact version.

import results from "../../../../benchmark/results.json";

export interface Score {
  support: number;
  truePositives: number;
  falsePositives: number;
  falseNegatives: number;
  precision: number;
  recall: number;
  f1: number;
}

export interface ErrorExample {
  kind: "false-positive" | "false-negative";
  type: string;
  recordId: string;
  text: string;
  start: number;
  end: number;
}

export interface BenchmarkResults {
  version: string;
  records: number;
  cleanRecords: number;
  entities: number;
  overall: Score;
  byType: Record<string, Score>;
  cleanRecordsWithFindings: number;
  errors: ErrorExample[];
}

export const benchmark = results as BenchmarkResults;

export const DATASET_URL = "https://github.com/privyl/privyl/blob/main/benchmark/dataset.jsonl";
export const RESULTS_URL = "https://github.com/privyl/privyl/blob/main/benchmark/results.json";
export const CODE_URL = "https://github.com/privyl/privyl/tree/main/benchmark";
